class OrderedMember(Component):
    """
    A member of an ordered collection serving as a proxy for a real world item, which can appear in different orders in different collections. The ordered member appears in exactly one ordered collection.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'class_uri': 'gist:OrderedMember',
         'comments': ['An ordered member points to the real world item via the '
                      'providesOrderFor property. Ordering information is represented '
                      'either as a number in a sequence, or by preceding or following '
                      'another ordered member.'],
         'examples': [{'value': 'A person may rank 12th in the Boston Marathon but '
                                '29th in the New York City Marathon.'}],
         'from_schema': 'https://w3id.org/lmodel/gist/core',
         'in_subset': ['gist_core'],
         'notes': ['OWL equivalentClass: (gist:Component & '
                   '(∃precedesDirectly.gist:OrderedMember | '
                   '∃^precedesDirectly.gist:OrderedMember | ∃sequence.xsd:integer) & '
                   '∃providesOrderFor.owl:Thing & ∀isMemberOf.gist:OrderedCollection & '
                   '=1isMemberOf)'],
         'title': 'Ordered Member'})

    is_first_member_of: Optional[list[OrderedCollection]] = Field(default=None, title="is first member of", description="""Relates the first member of an ordered collection to the collection.""", json_schema_extra = { "linkml_meta": {'comments': ['Given the Open World Assumption, the absence of a predecessor '
                      'does not entail that an ordered member is the first member of '
                      'an ordered collection. This property is used to explicitly '
                      'indicate the first member. Since ordered collections need not '
                      'be strictly ordered, there can be more than one first member.'],
         'domain': 'OrderedMember',
         'domain_of': ['OrderedMember'],
         'in_subset': ['gist_core'],
         'is_a': 'is_member_of',
         'slot_uri': 'gist:isFirstMemberOf'} })
